import React, { useState, useMemo, useEffect } from "react";
import { useParams } from "react-router-dom";

function Games({ onGameWin }) {
  const { subId } = useParams();
  const user = JSON.parse(localStorage.getItem("user"));
  const [selectedTopic, setSelectedTopic] = useState("Biology");
  const [progress, setProgress] = useState({});
  const [processingId, setProcessingId] = useState(null);

  useEffect(() => {
    console.log("🎮 Games component loaded!");
    console.log("🎮 User:", user?.firstName || "Guest");
    console.log("🎮 SubId from params:", subId);
  }, []);

  // Comprehensive game data - 10 games per science topic
  const gamesByTopic = {
    Biology: [
      { id: 1, game_number: 1, title: "Cell Structure Master", description: "Identify cell organelles and their functions. Match organelles to their descriptions.", lesson: "Introduction to Biology", base_reward: 50, coin_cost: 10 },
      { id: 2, game_number: 2, title: "Photosynthesis Puzzle", description: "Guide plants through photosynthesis. Learn light and dark reactions.", lesson: "Photosynthesis & Cellular Respiration", base_reward: 60, coin_cost: 15 },
      { id: 3, game_number: 3, title: "Evolution Match", description: "Connect species to their evolutionary adaptations. Understand natural selection.", lesson: "Evolution & Natural Selection", base_reward: 60, coin_cost: 15 },
      { id: 4, game_number: 4, title: "Genetics Inheritance", description: "Create Punnett squares to predict offspring traits.", lesson: "Genetics & Heredity", base_reward: 70, coin_cost: 20 },
      { id: 5, game_number: 5, title: "DNA Sequencer", description: "Arrange DNA bases in correct order. Learn genetic coding.", lesson: "DNA & Molecular Biology", base_reward: 70, coin_cost: 20 },
      { id: 6, game_number: 6, title: "Ecosystem Builder", description: "Create balanced ecosystems with food chains and energy flow.", lesson: "Ecology & Ecosystems", base_reward: 60, coin_cost: 15 },
      { id: 7, game_number: 7, title: "Population Simulator", description: "Manage population growth and limiting factors.", lesson: "Population Dynamics", base_reward: 70, coin_cost: 20 },
      { id: 8, game_number: 8, title: "Anatomy Labeler", description: "Label human body systems and organs correctly.", lesson: "Human Body Systems", base_reward: 60, coin_cost: 15 },
      { id: 9, game_number: 9, title: "Immune Response", description: "Learn how immune cells fight infections and disease.", lesson: "Immune System & Disease", base_reward: 70, coin_cost: 20 },
      { id: 10, game_number: 10, title: "Taxonomy Challenge", description: "Classify organisms using the binomial nomenclature system.", lesson: "Classification & Taxonomy", base_reward: 60, coin_cost: 15 },
    ],
    Chemistry: [
      { id: 11, game_number: 1, title: "Periodic Table Master", description: "Learn elements, symbols, and periodic trends.", lesson: "Atomic Structure & Periodic Table", base_reward: 50, coin_cost: 10 },
      { id: 12, game_number: 2, title: "Electron Configuration", description: "Fill electron shells with correct orbital arrangement.", lesson: "Electrons & Energy Levels", base_reward: 60, coin_cost: 15 },
      { id: 13, game_number: 3, title: "Bonding Builder", description: "Form ionic, covalent, and metallic bonds.", lesson: "Chemical Bonding", base_reward: 70, coin_cost: 20 },
      { id: 14, game_number: 4, title: "Molecule Constructor", description: "Build molecules from atoms. Learn molecular structures.", lesson: "Molecular Geometry", base_reward: 60, coin_cost: 15 },
      { id: 15, game_number: 5, title: "Reaction Balancer", description: "Balance chemical equations and identify reaction types.", lesson: "Chemical Reactions", base_reward: 70, coin_cost: 20 },
      { id: 16, game_number: 6, title: "Stoichiometry Solver", description: "Calculate molar relationships in chemical reactions.", lesson: "Stoichiometry & Moles", base_reward: 80, coin_cost: 25 },
      { id: 17, game_number: 7, title: "Acid-Base Analyzer", description: "Determine pH and classify acids, bases, and salts.", lesson: "Acids, Bases & pH", base_reward: 70, coin_cost: 20 },
      { id: 18, game_number: 8, title: "Oxidation Redux", description: "Identify oxidation and reduction reactions.", lesson: "Redox & Electrochemistry", base_reward: 70, coin_cost: 20 },
      { id: 19, game_number: 9, title: "Thermochemistry Lab", description: "Calculate enthalpy and predict reaction energy changes.", lesson: "Thermochemistry & Energy", base_reward: 80, coin_cost: 25 },
      { id: 20, game_number: 10, title: "Kinetics Inspector", description: "Understand reaction rates and activation energy.", lesson: "Reaction Kinetics", base_reward: 70, coin_cost: 20 },
    ],
    Physics: [
      { id: 21, game_number: 1, title: "Force & Motion", description: "Apply Newton's laws to solve physics problems.", lesson: "Forces & Newton's Laws", base_reward: 50, coin_cost: 10 },
      { id: 22, game_number: 2, title: "Kinematics Calculator", description: "Calculate distance, velocity, and acceleration.", lesson: "Motion & Kinematics", base_reward: 60, coin_cost: 15 },
      { id: 23, game_number: 3, title: "Energy Transformer", description: "Convert between kinetic and potential energy.", lesson: "Work & Energy", base_reward: 60, coin_cost: 15 },
      { id: 24, game_number: 4, title: "Momentum Master", description: "Calculate momentum and collisions.", lesson: "Momentum & Impulse", base_reward: 70, coin_cost: 20 },
      { id: 25, game_number: 5, title: "Circular Motion", description: "Solve centripetal force and rotational problems.", lesson: "Circular Motion & Gravity", base_reward: 70, coin_cost: 20 },
      { id: 26, game_number: 6, title: "Wave Simulator", description: "Create and analyze waves, frequency, and wavelength.", lesson: "Waves & Sound", base_reward: 60, coin_cost: 15 },
      { id: 27, game_number: 7, title: "Optics Explorer", description: "Learn reflection, refraction, and light properties.", lesson: "Light & Optics", base_reward: 70, coin_cost: 20 },
      { id: 28, game_number: 8, title: "Electricity Circuits", description: "Build circuits and calculate current, voltage, resistance.", lesson: "Electricity & Circuits", base_reward: 70, coin_cost: 20 },
      { id: 29, game_number: 9, title: "Magnetism Field", description: "Visualize magnetic fields and electromagnetic forces.", lesson: "Magnetism & Electromagnetism", base_reward: 70, coin_cost: 20 },
      { id: 30, game_number: 10, title: "Quantum Quest", description: "Explore quantum mechanics and atomic models.", lesson: "Modern Physics & Quantum", base_reward: 80, coin_cost: 25 },
    ],
    "Environmental Science": [
      { id: 31, game_number: 1, title: "Biome Explorer", description: "Identify biomes and their characteristics worldwide.", lesson: "Earth's Biomes", base_reward: 50, coin_cost: 10 },
      { id: 32, game_number: 2, title: "Water Cycle Tracker", description: "Follow water through evaporation, condensation, precipitation.", lesson: "Water Cycle & Hydrosphere", base_reward: 60, coin_cost: 15 },
      { id: 33, game_number: 3, title: "Nutrient Cycling", description: "Track nitrogen, phosphorus, and carbon cycles.", lesson: "Nutrient Cycles", base_reward: 60, coin_cost: 15 },
      { id: 34, game_number: 4, title: "Weathering & Erosion", description: "Understand rock formation and soil development.", lesson: "Rocks, Minerals & Weathering", base_reward: 60, coin_cost: 15 },
      { id: 35, game_number: 5, title: "Weather Predictor", description: "Analyze weather patterns and atmospheric conditions.", lesson: "Weather & Atmosphere", base_reward: 70, coin_cost: 20 },
      { id: 36, game_number: 6, title: "Climate Modeler", description: "Simulate climate scenarios and predict changes.", lesson: "Climate & Climate Change", base_reward: 70, coin_cost: 20 },
      { id: 37, game_number: 7, title: "Conservation Hero", description: "Make decisions to protect endangered species and habitats.", lesson: "Biodiversity & Conservation", base_reward: 70, coin_cost: 20 },
      { id: 38, game_number: 8, title: "Pollution Fighter", description: "Identify pollution types and environmental solutions.", lesson: "Pollution & Environmental Issues", base_reward: 70, coin_cost: 20 },
      { id: 39, game_number: 9, title: "Renewable Energy", description: "Learn about solar, wind, and sustainable energy sources.", lesson: "Renewable & Sustainable Resources", base_reward: 70, coin_cost: 20 },
      { id: 40, game_number: 10, title: "Ecosystem Manager", description: "Balance human needs with ecosystem health.", lesson: "Human Impact & Sustainability", base_reward: 80, coin_cost: 25 },
    ],
    Economics: [
      { id: 41, game_number: 1, title: "Supply & Demand", description: "Balance markets and find equilibrium prices.", lesson: "Supply, Demand & Markets", base_reward: 50, coin_cost: 10 },
      { id: 42, game_number: 2, title: "Business Tycoon", description: "Run a virtual business with profit and loss.", lesson: "Business & Entrepreneurship", base_reward: 60, coin_cost: 15 },
      { id: 43, game_number: 3, title: "Budget Manager", description: "Create household and government budgets.", lesson: "Personal & Government Finance", base_reward: 60, coin_cost: 15 },
      { id: 44, game_number: 4, title: "Investment Trader", description: "Buy and sell stocks and build a portfolio.", lesson: "Stocks & Investments", base_reward: 70, coin_cost: 20 },
      { id: 45, game_number: 5, title: "GDP Calculator", description: "Measure economic growth and productivity.", lesson: "Macroeconomics & GDP", base_reward: 70, coin_cost: 20 },
      { id: 46, game_number: 6, title: "Inflation Monitor", description: "Manage inflation, unemployment, and interest rates.", lesson: "Inflation & Monetary Policy", base_reward: 70, coin_cost: 20 },
      { id: 47, game_number: 7, title: "Trade Navigator", description: "Understand international trade and tariffs.", lesson: "International Trade", base_reward: 70, coin_cost: 20 },
      { id: 48, game_number: 8, title: "Tax Planner", description: "Calculate taxes and optimize financial strategy.", lesson: "Taxation & Tax Planning", base_reward: 70, coin_cost: 20 },
      { id: 49, game_number: 9, title: "Labor Economics", description: "Understand wages, employment, and worker rights.", lesson: "Labor Economics", base_reward: 70, coin_cost: 20 },
      { id: 50, game_number: 10, title: "Economic Systems", description: "Compare capitalism, socialism, and mixed economies.", lesson: "Economic Systems & Theory", base_reward: 80, coin_cost: 25 },
    ],
    History: [
      { id: 51, game_number: 1, title: "Timeline Constructor", description: "Arrange historical events in correct order.", lesson: "Ancient Civilizations", base_reward: 50, coin_cost: 10 },
      { id: 52, game_number: 2, title: "Medieval Kingdoms", description: "Learn about feudalism and medieval society.", lesson: "Medieval Period", base_reward: 60, coin_cost: 15 },
      { id: 53, game_number: 3, title: "Renaissance Trivia", description: "Explore art, science, and culture rebirth.", lesson: "Renaissance & Reformation", base_reward: 60, coin_cost: 15 },
      { id: 54, game_number: 4, title: "Age of Exploration", description: "Track explorers and discovery of new lands.", lesson: "Age of Exploration", base_reward: 60, coin_cost: 15 },
      { id: 55, game_number: 5, title: "Revolution Puzzle", description: "Understand causes and effects of major revolutions.", lesson: "Revolutionary Movements", base_reward: 70, coin_cost: 20 },
      { id: 56, game_number: 6, title: "Industrial Era", description: "Learn about industrialization and social changes.", lesson: "Industrial Revolution", base_reward: 70, coin_cost: 20 },
      { id: 57, game_number: 7, title: "World War Historian", description: "Study major conflicts and their impacts.", lesson: "20th Century Wars", base_reward: 70, coin_cost: 20 },
      { id: 58, game_number: 8, title: "Cold War Strategies", description: "Understand geopolitical tensions and diplomacy.", lesson: "Cold War Period", base_reward: 70, coin_cost: 20 },
      { id: 59, game_number: 9, title: "Modern History Map", description: "Trace contemporary historical movements and events.", lesson: "Modern History & Globalization", base_reward: 70, coin_cost: 20 },
      { id: 60, game_number: 10, title: "Historical Figures", description: "Match leaders and thinkers with their achievements.", lesson: "Key Historical Figures", base_reward: 80, coin_cost: 25 },
    ],
    "Human Geography": [
      { id: 61, game_number: 1, title: "Map Master", description: "Identify countries, capitals, and geographic features.", lesson: "World Geography & Maps", base_reward: 50, coin_cost: 10 },
      { id: 62, game_number: 2, title: "Culture Explorer", description: "Learn about different cultures and traditions worldwide.", lesson: "Cultural Geography", base_reward: 60, coin_cost: 15 },
      { id: 63, game_number: 3, title: "Population Analyzer", description: "Study population distribution and demographics.", lesson: "Population & Demographics", base_reward: 60, coin_cost: 15 },
      { id: 64, game_number: 4, title: "Urban Planner", description: "Design sustainable cities and urban spaces.", lesson: "Urban Geography", base_reward: 70, coin_cost: 20 },
      { id: 65, game_number: 5, title: "Economic Regions", description: "Understand global economic zones and trade.", lesson: "Economic Geography", base_reward: 70, coin_cost: 20 },
      { id: 66, game_number: 6, title: "Political Boundaries", description: "Learn geopolitics and international borders.", lesson: "Political Geography", base_reward: 70, coin_cost: 20 },
      { id: 67, game_number: 7, title: "Resource Manager", description: "Manage natural resources sustainably.", lesson: "Natural Resources & Environment", base_reward: 70, coin_cost: 20 },
      { id: 68, game_number: 8, title: "Migration Tracker", description: "Understand human migration and diaspora.", lesson: "Migration & Diaspora", base_reward: 70, coin_cost: 20 },
      { id: 69, game_number: 9, title: "Climate & Landscape", description: "Explore climate zones and landforms.", lesson: "Climate & Landforms", base_reward: 70, coin_cost: 20 },
      { id: 70, game_number: 10, title: "Development Compass", description: "Compare economic development across regions.", lesson: "Development & Inequality", base_reward: 80, coin_cost: 25 },
    ],
    Psychology: [
      { id: 71, game_number: 1, title: "Cognitive Bias Detector", description: "Identify common thinking patterns and biases.", lesson: "Introduction to Psychology", base_reward: 50, coin_cost: 10 },
      { id: 72, game_number: 2, title: "Memory Mastermind", description: "Learn and test different types of memory.", lesson: "Sensation & Perception", base_reward: 60, coin_cost: 15 },
      { id: 73, game_number: 3, title: "Learning Pathways", description: "Understand classical and operant conditioning.", lesson: "Learning & Conditioning", base_reward: 60, coin_cost: 15 },
      { id: 74, game_number: 4, title: "Motivation Motivator", description: "Explore needs, drives, and motivation theories.", lesson: "Motivation & Emotion", base_reward: 70, coin_cost: 20 },
      { id: 75, game_number: 5, title: "Personality Puzzle", description: "Learn personality theories and assessment.", lesson: "Personality & Development", base_reward: 70, coin_cost: 20 },
      { id: 76, game_number: 6, title: "Social Dynamics", description: "Understand group behavior and social influence.", lesson: "Social Psychology", base_reward: 70, coin_cost: 20 },
      { id: 77, game_number: 7, title: "Mental Health Guide", description: "Learn about disorders and mental wellness.", lesson: "Mental Health & Disorders", base_reward: 70, coin_cost: 20 },
      { id: 78, game_number: 8, title: "Therapy Techniques", description: "Understand psychological treatments and therapy.", lesson: "Therapies & Interventions", base_reward: 70, coin_cost: 20 },
      { id: 79, game_number: 9, title: "Neuroscience Quest", description: "Explore brain structure and neurotransmitters.", lesson: "Biopsychology & Neuroscience", base_reward: 70, coin_cost: 20 },
      { id: 80, game_number: 10, title: "Research Methods", description: "Learn experimental design and statistical analysis.", lesson: "Research Methods & Statistics", base_reward: 80, coin_cost: 25 },
    ],
  };

  const topicGames = useMemo(() => gamesByTopic[selectedTopic] || [], [selectedTopic]);

  if (!user) return <h1 style={{ color: "white" }}>Please log in</h1>;

  async function playGame(game) {
    if (!user) return;
    setProcessingId(game.id);
    try {
      const res = await fetch("http://localhost:8080/game_progress/complete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, game_id: game.id }),
      });
      const data = await res.json();
      if (res.ok) {
        setProgress((p) => ({
          ...p,
          [game.id]: {
            ...(p[game.id] || {}),
            completed: (p[game.id]?.completed || 0) + 1,
            total_score: (p[game.id]?.total_score || 0) + (data.awarded_points || game.base_reward),
          },
        }));
        alert(data.message || `You earned ${data.awarded_points || game.base_reward} points!`);
        if (onGameWin && data.awarded_points) onGameWin(data.awarded_points, selectedTopic);
      } else {
        alert(data.message || "Game play failed");
      }
    } catch (err) {
      console.error(err);
      alert("Play failed");
    } finally {
      setProcessingId(null);
    }
  }

  return (
    <section className="page fade-in">
      <h1 className="slide-up">Games by Subject</h1>
      <p className="slide-up">Play games to earn points and master each topic!</p>

      {/* Topic Selection */}
      <div className="topic-selector" style={{ marginBottom: "32px" }}>
        <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", justifyContent: "center" }}>
          {Object.keys(gamesByTopic).map((topic) => (
            <button
              key={topic}
              className={`topic-btn ${selectedTopic === topic ? "active" : ""}`}
              onClick={() => setSelectedTopic(topic)}
              style={{
                padding: "10px 20px",
                borderRadius: "8px",
                border: "2px solid",
                fontSize: "14px",
                fontWeight: "600",
                cursor: "pointer",
                transition: "all 0.3s ease",
                borderColor: selectedTopic === topic ? "#06b6d4" : "#64748b",
                backgroundColor: selectedTopic === topic ? "rgba(6, 182, 212, 0.2)" : "transparent",
                color: selectedTopic === topic ? "#06b6d4" : "#cbd5e1",
              }}
            >
              {topic}
            </button>
          ))}
        </div>
      </div>

      {/* Games Grid */}
      <div className="games-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
        {topicGames.map((game) => {
          const pg = progress[game.id] || {};
          const completed = pg.completed || 0;

          return (
            <div key={game.id} className="card" style={{ marginBottom: 12, padding: "20px", borderRadius: "12px", border: "1px solid rgba(99, 102, 241, 0.3)", backgroundColor: "rgba(30, 41, 59, 0.6)" }}>
              <h3 style={{ margin: "0 0 8px 0", fontSize: "18px", color: "#ffffff" }}>{game.title}</h3>
              <p style={{ fontSize: "12px", color: "#94a3b8", margin: "0 0 12px 0" }}>Lesson: {game.lesson}</p>
              <p style={{ fontSize: "14px", color: "#cbd5e1", margin: "0 0 16px 0", minHeight: "40px" }}>{game.description}</p>

              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "16px" }}>
                <div style={{ fontSize: "13px", color: "#10b981", fontWeight: "600" }}>⭐ {game.base_reward} pts</div>
                <button
                  className="primary-btn"
                  disabled={processingId === game.id}
                  onClick={() => playGame(game)}
                  style={{
                    padding: "8px 16px",
                    borderRadius: "6px",
                    border: "none",
                    backgroundColor: "#6366f1",
                    color: "white",
                    cursor: processingId === game.id ? "not-allowed" : "pointer",
                    fontSize: "14px",
                    fontWeight: "600",
                    transition: "all 0.3s ease",
                    opacity: processingId === game.id ? 0.6 : 1,
                  }}
                  onMouseEnter={(e) => {
                    if (processingId !== game.id) e.target.style.backgroundColor = "#4f46e5";
                  }}
                  onMouseLeave={(e) => {
                    if (processingId !== game.id) e.target.style.backgroundColor = "#6366f1";
                  }}
                >
                  {completed > 0 ? `Played ${completed}x` : "Play Game"}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

export default Games;
